class Participant:
    """Scripted by the tests. vote is "yes", "no", "crash" (prepare raises TimeoutError) or "error" (prepare raises RuntimeError).
    Every call is recorded as (name, call) on a shared timeline; calls listed in fail_on raise ConnectionError after being recorded."""
    def __init__(self, name, timeline, vote="yes", fail_on=()):
        self.name = name
        self.timeline = timeline
        self.vote = vote
        self.fail_on = set(fail_on)

    def _record(self, call):
        self.timeline.append((self.name, call))
        if call in self.fail_on:
            raise ConnectionError(f"{self.name} is unreachable")

    def prepare(self):
        self._record("prepare")
        if self.vote == "crash":
            raise TimeoutError(f"{self.name} did not answer")
        if self.vote == "error":
            raise RuntimeError(f"{self.name} crashed")
        return self.vote == "yes"

    def commit(self):
        self._record("commit")

    def abort(self):
        self._record("abort")


def run(votes, fail_on=None):
    """votes: {name: "yes" | "no" | "crash" | "error"} in contact order; fail_on: {name: {"commit"}} makes that call raise.
    Returns (outcome, log, timeline), where timeline lists every call the coordinator really made."""
    timeline = []
    fail_on = fail_on or {}
    participants = {name: Participant(name, timeline, vote, fail_on.get(name, ())) for name, vote in votes.items()}
    result = run_two_phase_commit(participants)
    assert isinstance(result, (tuple, list)) and len(result) == 2, f"expected an (outcome, log) pair, got {result!r}"
    outcome, log = result
    return outcome, log, timeline


def same_log(actual, expected):
    assert isinstance(actual, list), f"the log must be a list of strings, got {actual!r}"
    for index, (got, want) in enumerate(zip(actual, expected)):
        assert got == want, f"log entry {index} is {got!r}, expected {want!r}; whole log: {actual!r}"
    assert len(actual) == len(expected), f"the log has {len(actual)} entries, expected {len(expected)}; whole log: {actual!r}"
    return True
